WITH valid_shipments AS (SELECT * FROM shipments WHERE delivered_date > '2023-06-01' AND cost >= 70 AND order_id IS NOT NULL), status_group_summary AS (SELECT CASE WHEN status IN ('LOST', 'RETURNED') THEN 'group_a' ELSE 'other' END status_group, DATE_FORMAT(shipped_date, 'yyyy-MM') shipped_month, MAX(cost) max_cost FROM valid_shipments GROUP BY CASE WHEN status IN ('LOST', 'RETURNED') THEN 'group_a' ELSE 'other' END, DATE_FORMAT(shipped_date, 'yyyy-MM')) SELECT * FROM status_group_summary WHERE max_cost < 71;
